const {test,before,after,beforeEach,afterEach}=require('node:test'),assert=require('node:assert/strict'),{randomUUID,createHash}=require('node:crypto'),{Client}=require('pg');
if(process.env.PGHOST!=='127.0.0.1'||!/^rva_hhl_gate_\d+_\d+$/.test(process.env.RVA_TEST_DATABASE||''))throw Error('Disposable Health & Hope Live database required');
const db=new Client(),q=(sql,args=[])=>db.query(sql,args),val=async(sql,args=[])=>Object.values((await q(sql,args)).rows[0])[0],digest=value=>createHash('sha256').update(value).digest('hex');
let owner,coach,inactive,pending,member,contact,other,session;
async function actor(uid,sql,args=[],role='authenticated'){await q('savepoint actor');try{await q('set local role '+role);await q("select set_config('request.jwt.claim.sub',$1,true)",[uid||'']);const result=await q(sql,args);await q('reset role');await q('release actor');return result;}catch(error){await q('rollback to actor');await q('release actor');throw error;}}
const service=(action,data={})=>actor(null,'select public.hhl_service_command($1,$2) result',[action,data],'service_role').then(r=>r.rows[0].result);
const staff=(uid,action,data={})=>actor(uid,'select public.hhl_staff_command($1,$2) result',[action,data]).then(r=>r.rows[0].result);
async function user(role,status='active',onboarding='complete'){const id=randomUUID();await q('insert into auth.users(id,email) values($1,$2)',[id,id+'@example.invalid']);if(role){await q('insert into public.staff_access(user_id,role,status,onboarding_status,contact_scope) values($1,$2,$3,$4,$5)',[id,role,status,onboarding,role==='coach'?'assigned':'all']);await q('update public.staff_access set onboarding_status=$2 where user_id=$1',[id,onboarding]);}return id;}
const input=(extra={})=>({request_id:randomUUID(),session_id:session,first_name:'Local',last_name:'Visitor',email:'local@example.invalid',event_notifications:true,marketing_requested:false,source:'health_hope_live_website',guest_model_version:'hhl-guest-v1',privacy_model_version:'hhl-privacy-v1',ip_hash:digest('fictional-ip'),...extra});
async function register(extra={}){await service('register',input(extra));return (await q('select * from private.hhl_registrations where session_id=$1 and email=$2',[extra.session_id||session,(extra.email||'local@example.invalid').toLowerCase().trim()])).rows[0];}
const saveSession=(extra={})=>staff(owner,'session-save',{regular_date:'2027-01-07',join_mode:'manual',manual_join_url:'https://zoom.us/j/12345678901?pwd=fictional',status:'published',reason:'Local fixture session configuration',...extra});
before(()=>db.connect());after(()=>db.end());beforeEach(async()=>{
 await q('begin');
 for(const key of ['crm.view','crm.manage']){await q('insert into public.staff_permission_catalog(permission_key,label,category) values($1,$1,$2) on conflict do nothing',[key,'CRM']);for(const role of ['owner','admin','coach'])await q('insert into public.staff_role_permission_defaults(role,permission_key,allowed) values($1,$2,true) on conflict(role,permission_key) do update set allowed=true',[role,key]);}
 owner=await user('owner');coach=await user('coach');inactive=await user('owner','inactive');pending=await user('owner','active','pending');member=await user(null);
 contact=await val("insert into public.contacts(first_name,last_name,email,assigned_to) values('Local','Visitor','local@example.invalid',$1) returning id",[coach]);
 other=await val("insert into public.contacts(first_name,last_name,email) values('Other','Person','other@example.invalid') returning id");
 session=(await saveSession()).session_id;await q('update private.hhl_settings set registration_enabled=true,retention_enabled=true,provider_retention_ready=true,retention_healthy_at=now()');
});afterEach(()=>q('rollback'));

test('RLS and direct ACLs protect every new private table from anonymous, member, staff and service roles',async()=>{const rows=(await q("select c.relname,c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relkind='r' and c.relname like 'hhl_%'")).rows;assert.equal(rows.length,11);for(const row of rows){assert(row.relrowsecurity);for(const role of ['anon','authenticated','service_role'])await assert.rejects(actor(owner,'select * from private.'+row.relname,[],role),/permission denied/);}});
test('service API cannot be called by browser roles; staff API cannot be called anonymously or with service identity',async()=>{for(const role of ['anon','authenticated'])await assert.rejects(actor(owner,"select public.hhl_service_command('sessions')",[],role),/permission denied/);for(const role of ['anon','service_role'])await assert.rejects(actor(null,"select public.hhl_staff_command('overview')",[],role),/permission denied/);});
test('ordinary members, inactive/pending staff and explicit denies cannot read or manage event history',async()=>{for(const uid of [member,inactive,pending])await assert.rejects(staff(uid,'overview'),/event_access_denied/);await q("insert into public.staff_permission_overrides(user_id,permission_key,allowed,updated_by) values($1,'crm.view',false,$1)",[owner]);await assert.rejects(staff(owner,'overview'),/event_access_denied/);});
test('only complete Owner/Admin CRM managers may manage the global schedule',async()=>{assert.equal((await staff(coach,'overview')).can_manage,false);await assert.rejects(staff(coach,'settings',{registration_enabled:true,zoom_enabled:true,notifications_enabled:true,reason:'Attempted global control'}),/event_management_denied/);});
test('held registration exposes no dates and creates no participation rows',async()=>{await q('update private.hhl_settings set registration_enabled=false');assert.deepEqual((await service('sessions')).sessions,[]);await assert.rejects(service('register',input()),/registration_unavailable/);assert.equal(Number(await val('select count(*) from private.hhl_registrations')),0);});
test('public schedule contains only available confirmed sessions and no private joining details',async()=>{const next=(await saveSession({regular_date:'2027-01-14'})).session_id;await q("update private.hhl_sessions set status='cancelled' where id=$1",[session]);const data=await service('sessions');assert.equal(data.sessions.length,1);assert.equal(data.sessions[0].id,next);assert.doesNotMatch(JSON.stringify(data),/zoom\.us|pwd|meeting_id|contact/);});
test('closed, draft and canceled sessions reject registration at the database boundary',async()=>{for(const status of ['draft','cancelled']){await q('update private.hhl_sessions set status=$2 where id=$1',[session,status]);await assert.rejects(service('register',input()),/session_unavailable/);}await q("update private.hhl_sessions set status='published',closes_at=now() where id=$1",[session]);await assert.rejects(service('register',input()),/session_unavailable/);});
test('weekly default uses New York time across both Eastern DST transitions',async()=>{for(const[date,expected]of [['2026-10-29','2026-10-29T22:30:00.000Z'],['2026-11-05','2026-11-05T23:30:00.000Z'],['2027-03-11','2027-03-11T23:30:00.000Z'],['2027-03-18','2027-03-18T22:30:00.000Z']]){const id=(await saveSession({regular_date:date})).session_id;assert.equal((await val('select starts_at from private.hhl_sessions where id=$1',[id])).toISOString(),expected);}});
test('regular dates must be Thursday; ambiguous/nonexistent exception times are rejected',async()=>{await assert.rejects(saveSession({regular_date:'2027-01-08'}),/check constraint/);await assert.rejects(saveSession({regular_date:'2027-03-11',eastern_start:'2027-03-14T02:30'}),/ambiguous_or_nonexistent/);await assert.rejects(saveSession({regular_date:'2026-10-29',eastern_start:'2026-11-01T01:30'}),/ambiguous_or_nonexistent/);});
test('same-session returning registration is deduplicated and does not overwrite existing contact or consent',async()=>{const before=(await q('select * from public.contacts where id=$1',[contact])).rows[0];const a=await register();const b=await register({marketing_requested:true});assert.equal(a.id,b.id);assert.equal(b.marketing_requested,false);assert.equal(b.contact_id,contact);assert.deepEqual((await q('select * from public.contacts where id=$1',[contact])).rows[0],before);assert.equal(Number(await val('select count(*) from private.hhl_jobs')),2);});
test('a returning visitor registers separately next week on the same master contact',async()=>{await register();const next=(await saveSession({regular_date:'2027-01-14'})).session_id;const second=await register({session_id:next,email:' LOCAL@EXAMPLE.INVALID ',marketing_requested:true});assert.equal(second.contact_id,contact);const history=await staff(owner,'history',{contact_id:contact});assert.equal(history.length,2);assert.equal(Number(await val("select count(*) from public.contacts where lower(trim(email))='local@example.invalid'")),1);});
test('new email creates one Registered Guest without paid/member/assessment state',async()=>{const tables=['client_access','client_memberships','client_course_enrollments','profiles','workflow_records','webinar_registrations','journey_enrollment_activations','payment_records'];const before=await Promise.all(tables.map(t=>val('select count(*) from public.'+t)));const users=await val('select count(*) from auth.users');const r=await register({email:'new@example.invalid'});assert(r.contact_id);assert.equal(await val('select lifecycle_stage from public.contacts where id=$1',[r.contact_id]),'registered_guest');assert.equal(await val("select first_source from public.contacts where id=$1",[r.contact_id]),'health_hope_live');assert.equal(Number(await val("select count(*) from public.contact_tags where contact_id=$1 and tag='health_hope_live_guest'",[r.contact_id])),1);for(const [i,table]of tables.entries())assert.equal(await val('select count(*) from public.'+table),before[i],table);assert.equal(await val('select count(*) from auth.users'),users);});
test('ambiguous existing email and conflicting person names are held without merging or creating contacts',async()=>{await q("insert into public.contacts(first_name,last_name,email) values('Duplicate','Person',' local@example.invalid ')");const count=Number(await val('select count(*) from public.contacts'));let r=await register();assert.equal(r.state,'identity_review');assert.equal(r.contact_id,null);assert.equal(Number(await val('select count(*) from public.contacts')),count);assert.equal(Number(await val('select count(*) from private.hhl_jobs')),0);await q('delete from private.hhl_requests');await q('delete from private.hhl_registrations');r=await register({email:'other@example.invalid',first_name:'Unrelated',last_name:'Name'});assert.equal(r.state,'identity_review');assert.equal(r.contact_id,null);});
test('request UUID replay is stable and changed payloads conflict without duplicate jobs',async()=>{const body=input();await service('register',body);await service('register',body);await assert.rejects(service('register',{...body,last_name:'Changed'}),/request_conflict/);assert.equal(Number(await val('select count(*) from private.hhl_requests')),1);assert.equal(Number(await val('select count(*) from private.hhl_jobs')),2);});
test('malformed consent, source, extra fields and unbounded names are rejected server-side',async()=>{for(const extra of [{event_notifications:false},{marketing_requested:'yes'},{source:'health_assessment'},{private_health:'nope'},{first_name:'x'.repeat(101)},{email:'bad'},{ip_hash:null}])await assert.rejects(service('register',input(extra)),/invalid_registration/);});
test('CRM contact scope filters counts and history; cross-contact requests cannot leak data',async()=>{await register();await register({email:'other@example.invalid',first_name:'Other',last_name:'Person'});const data=await staff(coach,'overview');assert.equal(data.people.length,1);assert.equal(data.people[0].contact_id,contact);assert.equal(data.sessions[0].registered,1);await assert.rejects(staff(coach,'history',{contact_id:other}),/event_access_denied/);assert.equal((await staff(owner,'overview')).people.length,2);});
test('joining information requires confirmed registration, current scope and an audit',async()=>{const r=await register();assert.match((await staff(coach,'join-info',{registration_id:r.id})).join_url,/zoom\.us/);assert.equal(Number(await val("select count(*) from private.hhl_audit where action='manual_join_info_access'")),1);await q('update public.contacts set assigned_to=null where id=$1',[contact]);await assert.rejects(staff(coach,'join-info',{registration_id:r.id}),/event_access_denied/);await q("update private.hhl_sessions set status='cancelled' where id=$1",[session]);await assert.rejects(staff(owner,'join-info',{registration_id:r.id}),/session_unavailable/);});
test('cancellation removes availability, preserves history, cancels old jobs and queues one update',async()=>{await register();await saveSession({id:session,revision:1,status:'cancelled'});assert.deepEqual((await service('sessions')).sessions,[]);assert.equal(await val('select state from private.hhl_registrations'),'cancelled');assert.equal(Number(await val("select count(*) from private.hhl_jobs where kind='cancellation'")),1);assert.equal(Number(await val("select count(*) from private.hhl_jobs where state='cancelled'")),2);assert.equal((await staff(owner,'history',{contact_id:contact})).length,1);});
test('rescheduling preserves original session identity and invalidates old job leases',async()=>{await register();await q('update private.hhl_settings set notifications_enabled=true');const lease=await service('claim',{allow_notifications:true});assert(lease);await saveSession({id:session,revision:1,eastern_start:'2027-01-08T18:30',reason:'Move fictional event to Friday due to exception'});await assert.rejects(service('finish',{...lease,state:'done'}),/job_unavailable/);assert.equal(await val('select regular_date::text from private.hhl_sessions where id=$1',[session]),'2027-01-07');assert.equal(Number(await val("select count(*) from private.hhl_jobs where state='pending' and revision=2")),2);});
test('stale session editors cannot overwrite a newer revision',async()=>{await saveSession({id:session,revision:1});await assert.rejects(saveSession({id:session,revision:1}),/session_revision_conflict/);});
test('provider and notification controls require database and caller release flags',async()=>{await register();assert.equal(await service('claim',{allow_notifications:true}),null);await q('update private.hhl_settings set notifications_enabled=true');assert.equal(await service('claim'),null);const lease=await service('claim',{allow_notifications:true});assert(lease);const job=await service('job',lease);assert.equal(job.kind,'confirmation');assert.match(job.join_url,/zoom\.us/);});
test('lease completion is idempotent by ownership; arbitrary and stale workers are denied',async()=>{await register();await q('update private.hhl_settings set notifications_enabled=true');const lease=await service('claim',{allow_notifications:true});await assert.rejects(service('finish',{id:lease.id,lease:randomUUID(),state:'done'}),/job_unavailable/);await service('finish',{...lease,state:'done',provider_id:'fictional-mail'});await assert.rejects(service('finish',{...lease,state:'done'}),/job_unavailable/);});
test('Zoom session cannot be published without validated matching occurrence',async()=>{await assert.rejects(saveSession({regular_date:'2027-01-14',join_mode:'zoom',zoom_meeting_id:'12345678901',zoom_occurrence_id:'fictional-occurrence',manual_join_url:null}),/zoom_validation_required/);});
test('unmatched Zoom identities remain reviewable and cannot create invented attendance',async()=>{await q('update private.hhl_settings set zoom_enabled=true');const event={event_key:digest('fictional-event'),meeting_id:'12345678901',instance_uuid:'unbound-instance',registrant_id:'unmatched',observed_at:new Date().toISOString()};await service('attendance',event);await service('attendance',event);assert.equal(Number(await val('select count(*) from private.hhl_attendance')),1);assert.equal(await val('select state from private.hhl_attendance'),'review');assert.equal(Number(await val('select count(*) from private.hhl_registrations where attended_at is not null')),0);});
test('confirmed Zoom registrant and exact instance credit attendance once; name/email guessing is absent',async()=>{const r=await register();await q("update private.hhl_sessions set regular_date=(date_trunc('week',now() AT TIME ZONE 'America/New_York')::date+3),starts_at=now()-interval '5 minutes',closes_at=now()-interval '5 minutes',zoom_meeting_id='12345678901',zoom_occurrence_id='occ1',zoom_instance_uuid='known-instance',zoom_validated_at=now() where id=$1",[session]);await q("update private.hhl_registrations set zoom_registrant_id='known-registrant' where id=$1",[r.id]);await q('update private.hhl_settings set zoom_enabled=true');const event={event_key:digest('matched-event'),meeting_id:'12345678901',instance_uuid:'known-instance',registrant_id:'known-registrant',observed_at:new Date().toISOString()};await service('attendance',event);await service('attendance',event);assert.equal(await val('select state from private.hhl_attendance'),'matched');assert.equal(Number(await val('select count(*) from private.hhl_registrations where attended_at is not null')),1);assert.equal((await staff(owner,'overview')).people[0].attended,1);});
test('identity resolution requires scoped existing email and a reason, never a new client record',async()=>{const r=await register({first_name:'Different'});assert.equal(r.state,'identity_review');await assert.rejects(staff(owner,'identity-resolve',{registration_id:r.id,contact_id:other,reason:'Reviewed fictional identity'}),/identity_mismatch/);await assert.rejects(staff(owner,'identity-resolve',{registration_id:r.id,contact_id:contact,reason:''}),/review_reason_required/);await staff(owner,'identity-resolve',{registration_id:r.id,contact_id:contact,reason:'Verified existing person in local fixture'});assert.equal(await val('select contact_id from private.hhl_registrations'),contact);assert.equal(Number(await val('select count(*) from private.hhl_jobs')),2);});
test('expired mail leases retain one stable job identity; uncertain Zoom leases require review',async()=>{const r=await register();await q('update private.hhl_settings set notifications_enabled=true,zoom_enabled=true');let lease=await service('claim',{allow_notifications:true});await q("update private.hhl_jobs set leased_at=now()-interval '4 minutes' where id=$1",[lease.id]);const again=await service('claim',{allow_notifications:true});assert.equal(again.id,lease.id);assert.notEqual(again.lease,lease.lease);await q("update private.hhl_jobs set kind='zoom',leased_at=now()-interval '4 minutes' where id=$1",[again.id]);assert.equal(await service('claim',{allow_zoom:true}),null);assert.equal(await val('select state from private.hhl_jobs where id=$1',[again.id]),'review');assert.equal(await val('select last_error from private.hhl_jobs where id=$1',[again.id]),'zoom_outcome_uncertain');});
test('mail retries stop before the provider idempotency window expires',async()=>{await register();await q('update private.hhl_settings set notifications_enabled=true');const lease=await service('claim',{allow_notifications:true});await q("update private.hhl_jobs set leased_at=now()-interval '4 minutes',first_attempt_at=now()-interval '24 hours' where id=$1",[lease.id]);assert.equal(await service('claim',{allow_notifications:true}),null);assert.equal(await val('select state from private.hhl_jobs where id=$1',[lease.id]),'review');});
test('manual joining mode can reconcile an observed Zoom instance with documented human review',async()=>{const r=await register();await q("update private.hhl_sessions set regular_date=(date_trunc('week',now() AT TIME ZONE 'America/New_York')::date+3),starts_at=now()-interval '5 minutes',closes_at=now()-interval '5 minutes' where id=$1",[session]);await q('update private.hhl_settings set zoom_enabled=true');const event={event_key:digest('manual-instance-observation'),meeting_id:'12345678901',instance_uuid:'manual-instance',registrant_id:null,observed_at:new Date().toISOString()};await service('attendance',event);await assert.rejects(staff(coach,'bind-instance',{session_id:session,meeting_id:'12345678901',instance_uuid:'manual-instance',reason:'Observe fictional session'}),/event_management_denied/);await staff(owner,'bind-instance',{session_id:session,meeting_id:'12345678901',instance_uuid:'manual-instance',reason:'Verified the observed meeting and session timestamp'});await staff(owner,'attendance-resolve',{event_key:event.event_key,registration_id:r.id,reason:'Human verified intended registrant from event evidence'});assert.equal(await val('select state from private.hhl_attendance'),'matched');assert.equal((await staff(owner,'overview')).people[0].attended,1);});
test('limited-scope Owner cannot enumerate unresolved identities or attendance outside CRM scope',async()=>{await q("update public.staff_access set contact_scope='assigned' where user_id=$1",[owner]);await assert.rejects(staff(owner,'review-list',{reason:'Attempt global identity enumeration'}),/event_access_denied/);});
test('recorded event-notice withdrawal cancels queued mail and preserves attendance and consent history',async()=>{const r=await register({marketing_requested:true});await q('update private.hhl_settings set notifications_enabled=true');await staff(owner,'withdraw-consent',{registration_id:r.id,withdraw_event:true,withdraw_marketing:false,reason:'Recipient asked to stop event email notices'});assert.equal(await val('select event_notifications from private.hhl_registrations'),false);assert.equal(await val('select marketing_requested from private.hhl_registrations'),true);assert(await val('select event_notices_withdrawn_at from private.hhl_registrations'));assert.equal(await service('claim',{allow_notifications:true}),null);assert.equal((await staff(owner,'history',{contact_id:contact})).length,1);await assert.rejects(staff(coach,'withdraw-consent',{registration_id:r.id,withdraw_event:true,reason:'Unauthorized coach attempted withdrawal'}),/event_management_denied/);});
test('weekly draft preparation follows Eastern DST and preserves canceled dates without advertising new availability',async()=>{const next=(await saveSession({regular_date:'2026-11-05',status:'cancelled'})).session_id;await staff(owner,'prepare-weekly',{first_thursday:'2026-10-29',weeks:3,reason:'Prepare a reviewed run of fictional Thursday drafts'});assert.equal(await val('select status from private.hhl_sessions where id=$1',[next]),'cancelled');const draft=(await q("select regular_date::text as scheduled_day,starts_at,status from private.hhl_sessions where regular_date in ('2026-10-29','2026-11-12') order by regular_date")).rows;assert.equal(draft.length,2);assert(draft.every(row=>row.status==='draft'));assert.equal(draft[0].starts_at.toISOString(),'2026-10-29T22:30:00.000Z');assert.equal(draft[1].starts_at.toISOString(),'2026-11-12T23:30:00.000Z');assert.equal((await service('sessions')).sessions.length,1);await assert.rejects(staff(coach,'prepare-weekly',{first_thursday:'2026-10-29',weeks:3,reason:'A restricted manager cannot schedule globally'}),/event_management_denied/);});
test('Zoom cancellation removes public availability and queues only one cancellation per webhook',async()=>{await register();await q('update private.hhl_settings set zoom_enabled=true');const event={event_key:digest('provider-cancel'),meeting_id:'12345678901',kind:'deleted'};await service('zoom-change',event);await service('zoom-change',event);assert.equal(await val('select status from private.hhl_sessions where id=$1',[session]),'cancelled');assert.equal(await val('select revision from private.hhl_sessions where id=$1',[session]),2);assert.equal(Number(await val("select count(*) from private.hhl_jobs where kind='cancellation'")),1);assert.deepEqual((await service('sessions')).sessions,[]);});
test('Zoom schedule updates hold a published session for review without inventing a new time',async()=>{await register();await q('update private.hhl_settings set zoom_enabled=true');await service('zoom-change',{event_key:digest('provider-update'),meeting_id:'12345678901',kind:'updated'});assert.equal(await val('select status from private.hhl_sessions where id=$1',[session]),'draft');assert.equal(await val('select state from private.hhl_registrations'),'confirmed');assert.deepEqual((await service('sessions')).sessions,[]);assert.equal(Number(await val("select count(*) from private.hhl_jobs where state='pending'")),0);});
test('Zoom availability expires without a recent provider validation',async()=>{await q("update private.hhl_sessions set join_mode='zoom',zoom_occurrence_id='fictional-occurrence',zoom_validated_at=now()-interval '11 minutes' where id=$1",[session]);await q('update private.hhl_settings set zoom_enabled=true');assert.deepEqual((await service('sessions')).sessions,[]);await assert.rejects(service('register',input()),/session_unavailable/);await service('zoom-sync',{session_id:session,meeting_id:'12345678901',occurrence_id:'fictional-occurrence',starts_at:'2027-01-07T23:30:00Z'});assert.equal((await service('sessions')).sessions.length,1);});
test('participant search reaches older event history while preserving CRM contact scope',async()=>{await register();await register({email:'other@example.invalid',first_name:'Other',last_name:'Person'});assert.equal((await staff(owner,'overview',{query:'other@example.invalid'})).people[0].contact_id,other);assert.equal((await staff(owner,'overview',{query:contact})).people[0].contact_id,contact);assert.equal((await staff(coach,'overview',{query:'other@example.invalid'})).people.length,0);});
test('provider changes invalidate old private Zoom joining information before new notices can run',async()=>{const r=await register();await q("update private.hhl_sessions set join_mode='zoom',zoom_occurrence_id='fictional-occurrence',zoom_validated_at=now() where id=$1",[session]);await q("update private.hhl_registrations set zoom_registrant_id='fictional-registrant',zoom_join_url='https://zoom.us/j/12345678901?pwd=old' where id=$1",[r.id]);await q('update private.hhl_settings set zoom_enabled=true');await service('zoom-change',{event_key:digest('provider-join-update'),meeting_id:'12345678901',kind:'updated'});assert.equal(await val('select state from private.hhl_registrations'),'pending');assert.equal(await val('select zoom_join_url from private.hhl_registrations'),null);await assert.rejects(staff(owner,'join-info',{registration_id:r.id}),/event_access_denied/);});

// Approved guest model: CRM identity is shared; event participation is private.
test('legacy CRM relationships are never downgraded or requalified by event registration',async()=>{
 for(const stage of ['lead','assessment_lead','webinar_lead','applicant','client','inactive','engaged_guest','prospective_client']){
  const email=stage+'@example.invalid';const id=await val("insert into public.contacts(first_name,last_name,email,lifecycle_stage,first_source,last_source) values('Local','Visitor',$1,$2,'existing-source','existing-source') returning id",[email,stage]);
  const before=(await q('select * from public.contacts where id=$1',[id])).rows[0];const r=await register({email});assert.equal(r.contact_id,id);assert.deepEqual((await q('select * from public.contacts where id=$1',[id])).rows[0],before);
  assert.equal(Number(await val("select count(*) from public.contact_tags where contact_id=$1 and tag='health_hope_live_guest'",[id])),1);
 }
});
test('a repeat guest keeps one master identity and Registered Guest status across weekly sessions',async()=>{
 const first=await register({email:'guest@example.invalid'});const next=(await saveSession({regular_date:'2027-01-14'})).session_id;const second=await register({email:' GUEST@EXAMPLE.INVALID ',session_id:next});assert.equal(first.contact_id,second.contact_id);assert.equal(await val('select lifecycle_stage from public.contacts where id=$1',[first.contact_id]),'registered_guest');assert.equal(Number(await val('select count(*) from public.contact_tags where contact_id=$1',[first.contact_id])),1);
 const person=(await staff(owner,'overview')).people.find(p=>p.contact_id===first.contact_id);assert.equal(person.registered,2);assert.equal(person.relationship_stage,'registered_guest');assert.equal(person.guest_classification,'registered_guest');assert.equal(person.active_client,false);assert.equal(person.can_progress,true);
});
test('guest stages advance only by deliberate scoped manager actions and retain auditable reasons',async()=>{
 const r=await register({email:'guest@example.invalid'});const data={contact_id:r.contact_id,expected_stage:'registered_guest',stage:'engaged_guest',reason:'Staff reviewed an explicit conversation with this guest'};
 await assert.rejects(staff(owner,'guest-stage',{...data,stage:'prospective_client'}),/invalid_guest_progression/);
 await assert.rejects(staff(owner,'guest-stage',{...data,stage:'client'}),/invalid_guest_progression/);
 await assert.rejects(staff(owner,'guest-stage',{...data,reason:''}),/review_reason_required/);
 await staff(owner,'guest-stage',data);
 await assert.rejects(staff(owner,'guest-stage',data),/guest_stage_conflict/);
 await staff(owner,'guest-stage',{...data,expected_stage:'engaged_guest',stage:'prospective_client',reason:'Guest requested a consultation; staff confirmed their interest'});
 assert.equal(await val('select lifecycle_stage from public.contacts where id=$1',[r.contact_id]),'prospective_client');
 assert.equal(Number(await val("select count(*) from private.hhl_audit where subject_id=$1 and action like 'guest-stage:%' and actor_id=$2 and length(reason)>=5",[r.contact_id,owner])),2);
 assert.equal(Number(await val("select count(*) from public.contact_activity where contact_id=$1 and activity_type='hhl_guest_progression' and metadata->>'source'='health_hope_live'",[r.contact_id])),2);
 for(const table of ['client_access','client_memberships','journey_enrollment_activations','workflow_records'])assert.equal(Number(await val('select count(*) from public.'+table)),0);
 await assert.rejects(staff(owner,'guest-stage',{...data,expected_stage:'prospective_client',stage:'client'}),/invalid_guest_progression/);
});
test('guest progression cannot bypass onboarding, CRM permissions or contact scope',async()=>{
 const r=await register({email:'guest@example.invalid'}),data={contact_id:r.contact_id,expected_stage:'registered_guest',stage:'engaged_guest',reason:'Attempted change of guest relationship'};
 for(const uid of [member,inactive,pending])await assert.rejects(staff(uid,'guest-stage',data),/event_access_denied/);
 await assert.rejects(staff(coach,'guest-stage',data),/event_management_denied/);
 await q("update public.staff_access set contact_scope='assigned' where user_id=$1",[owner]);await assert.rejects(staff(owner,'guest-stage',data),/event_access_denied/);
 await q('update public.contacts set assigned_to=$2 where id=$1',[r.contact_id,owner]);await q("insert into public.staff_permission_overrides(user_id,permission_key,allowed,updated_by) values($1,'crm.manage',false,$1)",[owner]);await assert.rejects(staff(owner,'guest-stage',data),/event_management_denied/);
});
