async function completedSession(){await q("update private.hhl_sessions set regular_date=date_trunc('week',now() AT TIME ZONE 'America/New_York')::date+3,starts_at=now()-interval '1 hour',closes_at=now()-interval '1 hour',zoom_instance_uuid='reviewed-instance' where id=$1",[session]);}
test('absence stays unreviewed until staff records a completed-session no-show; cancellations remain distinct',async()=>{
 const r=await register();let history=await staff(owner,'history',{contact_id:contact});assert.equal(history[0].attendance_status,'unreviewed');
 const data={registration_id:r.id,attendance_status:'no_show',expected_status:'unreviewed',reason:'Staff reconciled completed meeting attendance report'};
 await assert.rejects(staff(owner,'attendance-status',data),/invalid_attendance_status/);await completedSession();
 await assert.rejects(staff(coach,'attendance-status',data),/event_management_denied/);await staff(owner,'attendance-status',data);
 history=await staff(owner,'history',{contact_id:contact});assert.equal(history[0].attendance_status,'no_show');assert.equal(history[0].session_status,'published');
 assert.equal(Number(await val("select count(*) from private.hhl_audit where subject_id=$1 and action='attendance-status:unreviewed:no_show'",[r.id])),1);
 await assert.rejects(staff(owner,'attendance-status',data),/attendance_status_conflict/);
 await staff(owner,'attendance-status',{...data,attendance_status:'unreviewed',expected_status:'no_show'});
 await q("update private.hhl_sessions set status='cancelled' where id=$1",[session]);await assert.rejects(staff(owner,'attendance-status',data),/invalid_attendance_status/);
 assert.equal((await staff(owner,'history',{contact_id:contact}))[0].attendance_status,'cancelled');
});
test('unmatched Zoom identities prevent guessed no-shows and late verified attendance corrects them without promotion',async()=>{
 const r=await register({email:'guest@example.invalid'});await completedSession();await q('update private.hhl_settings set zoom_enabled=true');await q("update private.hhl_registrations set zoom_registrant_id='verified-registrant' where id=$1",[r.id]);
 const unmatched={event_key:digest('unmatched-guest'),meeting_id:'12345678901',instance_uuid:'reviewed-instance',registrant_id:'unresolved',observed_at:new Date(Date.now()-45*60000).toISOString()};await service('attendance',unmatched);
 const data={registration_id:r.id,attendance_status:'no_show',expected_status:'unreviewed',reason:'Reviewed attendance evidence for this session'};
 await assert.rejects(staff(owner,'attendance-status',data),/attendance_review_required/);
 // Simulate a separately reviewed dismissal; never infer a match by name/email.
 await q("update private.hhl_attendance set state='dismissed' where event_key=$1",[unmatched.event_key]);await staff(owner,'attendance-status',data);
 await service('attendance',{...unmatched,event_key:digest('verified-guest'),registrant_id:'verified-registrant'});
 const history=await staff(owner,'history',{contact_id:r.contact_id});assert.equal(history[0].attendance_status,'verified_attended');assert.equal(await val('select attendance_status from private.hhl_registrations where id=$1',[r.id]),'unreviewed');assert.equal(await val('select lifecycle_stage from public.contacts where id=$1',[r.contact_id]),'registered_guest');
 assert.equal(Number(await val("select count(*) from private.hhl_audit where subject_id=$1 and action='no-show-corrected-by-verified-attendance'",[r.id])),1);
 await assert.rejects(staff(owner,'attendance-status',data),/invalid_attendance_status/);
});
test('old and missing server guest contracts cannot register against the new database',async()=>{for(const version of [undefined,'old'])await assert.rejects(service('register',input({guest_model_version:version})),/guest_model_required/);assert.equal(Number(await val('select count(*) from private.hhl_registrations')),0);});
test('new private trigger helpers are not executable by browser, staff or service roles',async()=>{for(const name of ['hhl_guest_link','hhl_attendance_correction']){const f=(await q("select prosecdef,proconfig from pg_proc where oid=$1::regprocedure",['private.'+name+'()'])).rows[0];assert(f.prosecdef);assert(f.proconfig.includes('search_path=""'));for(const role of ['anon','authenticated','service_role'])assert.equal(await val('select has_function_privilege($1,$2,\'execute\')',[role,'private.'+name+'()']),false);}});

