const maintain=()=>service('privacy-maintain',{allow_retention:true});
async function expireFixture(){await q("update private.hhl_sessions set regular_date='2025-01-02',starts_at='2025-01-02T23:30:00Z',closes_at='2025-01-02T23:30:00Z' where id=$1",[session]);}
test('twelve calendar months use the session end in New York, including leap years and DST',async()=>{
 for(const[start,end]of [['2024-02-29T23:30:00Z','2025-03-01T00:00:00Z'],['2025-03-13T22:30:00Z','2026-03-13T23:00:00Z'],['2025-11-06T23:30:00Z','2026-11-07T00:00:00Z']])assert.equal((await val('select private.hhl_expires_at($1)',[start])).toISOString(),new Date(end).toISOString());
});
test('registration and delivery stay held without a fresh enabled retention heartbeat and provider policy readiness',async()=>{
 for(const sql of ['retention_enabled=false','provider_retention_ready=false',"retention_healthy_at=now()-interval '6 minutes'"]){await q('savepoint readiness');await q('update private.hhl_settings set '+sql);await assert.rejects(service('register',input()),/privacy_readiness_required/);assert.deepEqual((await service('sessions')).sessions,[]);assert.equal(await service('claim',{allow_notifications:true}),null);await q('rollback to readiness');}
 await assert.rejects(service('register',input({privacy_model_version:undefined})),/privacy_model_required/);
});
test('expiry removes event identifiers and dependent records once, preserving master contacts and anonymous totals',async()=>{
 const r=await register();const before=(await q('select * from public.contacts where id=$1',[contact])).rows[0];await q("insert into public.contact_tags(contact_id,tag,source) values($1,'unrelated-tag','manual')",[contact]);await expireFixture();
 assert.deepEqual(await staff(owner,'history',{contact_id:contact}),[]);assert.equal((await staff(owner,'overview')).people.length,0);
 assert.equal((await maintain()).erased,1);assert.equal((await maintain()).erased,0);
 for(const t of ['hhl_registrations','hhl_jobs','hhl_requests','hhl_attendance'])assert.equal(Number(await val('select count(*) from private.'+t)),0,t);
 assert.deepEqual((await q('select * from public.contacts where id=$1',[contact])).rows[0],before);assert.equal(await val("select tag from public.contact_tags where contact_id=$1",[contact]),'unrelated-tag');
 const totals=(await q('select * from private.hhl_session_totals')).rows[0];assert.equal(Number(totals.registered),1);assert.equal(Number(totals.erased),1);assert(!JSON.stringify(totals).includes(contact));
 const s=(await q('select * from private.hhl_sessions where id=$1',[session])).rows[0];assert(s.expired_at);for(const key of ['manual_join_url','zoom_meeting_id','zoom_instance_uuid','zoom_occurrence_id'])assert.equal(s[key],null);
});
