test('verified deletion is idempotent, holds sends immediately, and leaves unrelated consent and CRM records intact',async()=>{
 const r=await register();const before=(await q('select * from public.contacts where id=$1',[contact])).rows[0];const req=randomUUID();const c=await privacyOpen('delete',contact,{request_id:req});assert.equal((await privacyOpen('delete',contact,{request_id:req})).case_id,c.case_id);
 assert.equal(await val('select privacy_hold from private.hhl_registrations where id=$1',[r.id]),true);assert.equal(await service('claim',{allow_notifications:true}),null);await assert.rejects(service('register',input()),/privacy_request_pending/);await assert.rejects(staff(owner,'join-info',{registration_id:r.id}),/event_access_denied/);
 const deleted=await staff(owner,'privacy-delete',{case_id:c.case_id});assert.equal(deleted.records_count,1);assert.deepEqual(await staff(owner,'privacy-delete',{case_id:c.case_id}),deleted);assert.deepEqual((await q('select * from public.contacts where id=$1',[contact])).rows[0],before);
 assert.equal(Number(await val('select count(*) from private.hhl_registrations')),0);assert.equal(Number(await val("select count(*) from private.hhl_privacy_log where action='deleted'")),1);
});
